 document.getElementById('opsList').innerHTML=arr.map(o=>{if(o.type==='Traspaso'){const pending=o.status==='pending';const detail=pending&&o.validationStatus==='nav_mismatch'?`Diferencia de VL: origen ${o.outDifferencePct==null?'—':o.outDifferencePct.toFixed(3)+'%'} · destino ${o.inDifferencePct==null?'—':o.inDifferencePct.toFixed(3)+'%'}`:'Pulsa para completar o validar los datos pendientes';return `<article class="op-card ${pending?'pending-editable':''}" ${pending?`data-edit-op="${esc(o.id)}"`:''}><div class="op-head"><div><div class="op-type">Traspaso</div><div class="muted" style="font-size:12px">Orden: ${esc(o.date)}</div>${pending?`<div class="pending-hint">${esc(detail)}</div>`:''}</div>${pending?'<div class="pending">⏸ Pendiente</div>':'<div class="metric-positive" style="font-size:12px">✓ Finalizado</div>'}</div><div class="op-flow"><div class="op-box"><strong>${entityWordmark(o.fromEntity)}</strong>${esc(meta({isin:o.from}).name)}<br><span class="muted">− ${eur(o.amount)}</span></div><div>→</div><div class="op-box"><strong>${entityWordmark(o.toEntity)}</strong>${esc(meta({isin:o.to}).name)}<br><span class="muted">+ ${eur(o.amount)}</span></div></div>${!pending&&o.outExecutionDate&&o.inExecutionDate?`<div class="pending-hint">Ejecución: salida ${esc(o.outExecutionDate)} · entrada ${esc(o.inExecutionDate)}</div>`:''}</article>`}if(o.type==='Recurrente'){const pending=o.pendingCount>0,reason=o.pendingReason==='currency_not_eur'?'requiere conversión histórica a EUR':'falta un VL/precio publicado para alguna fecha';return `<article class="op-card editable-operation ${pending?'pending-editable':''}" data-edit-recurring="${esc(o.id)}"><div class="op-head"><div><div class="op-type">Aportación recurrente${o.active?'':' · pausada'}</div><div class="muted" style="font-size:12px">${esc(recurrenceLabel(o.intervalMonths))} · día ${o.dayOfMonth} · desde ${esc(o.startDate)}</div><div class="pending-hint">${o.executedCount} ${o.executedCount===1?'aportación aplicada':'aportaciones aplicadas'}${pending?` · ${o.pendingCount} pendiente${o.pendingCount===1?'':'s'} (${esc(reason)})`:''}${o.nextDate?` · próxima ${esc(o.nextDate)}`:''}</div></div><strong>${eur(o.amount)}</strong></div><div class="op-box" style="margin-top:9px"><strong>${entityWordmark(o.entity)}</strong>${esc(meta({isin:o.isin}).name)}</div></article>`}const pending=o.status==='pending';const diff=o.navDifferencePct==null?'':` · diferencia ${o.navDifferencePct.toFixed(3)}%`;const baseLine=o.referenceBaseAmount?`<div class="pending-hint">Base 01/01/2026: ${eur(o.referenceBaseAmount)}</div>`:'';return `<article class="op-card editable-operation ${pending?'pending-editable':''}" data-edit-basic="${esc(o.id)}"><div class="op-head"><div><div class="op-type">${esc(o.type)}</div><div class="muted" style="font-size:12px">${o.type===REFERENCE_BASE_TYPE?'Datos actuales':'Orden: '+esc(o.date)+(o.executionDate?` · Ejecución: ${esc(o.executionDate)}`:'')}</div>${baseLine}<div class="pending-hint">${pending?'⏸ Pendiente de validar'+diff:'Pulsa para editar la operación'}</div></div><strong>${eur(o.referenceBaseAmount||o.amount)}</strong></div><div class="op-box" style="margin-top:9px"><strong>${entityWordmark(o.entity)}</strong>${esc(meta({isin:o.isin}).name)}</div></article>`}).join('')||'<div class="notice">No hay operaciones en este filtro.</div>';
