function recalcOperationField(field){const amount=numVal('fAmount'),shares=numVal('fShares'),nav=numVal('fOpNav');if(field==='amount'&&shares&&nav)document.getElementById('fAmount').value=(shares*nav).toFixed(2);if(field==='nav'&&amount&&shares)document.getElementById('fOpNav').value=(amount/shares).toFixed(6);if(field==='shares'&&amount&&nav)document.getElementById('fShares').value=(amount/nav).toFixed(8);updateTripletNotice()}
window.fillOperationThird=fillOperationThird;window.updateTripletNotice=updateTripletNotice;window.recalcOperationField=recalcOperationField;
function readOperationTriplet(){let amount=numVal('fAmount'),shares=numVal('fShares'),nav=numVal('fOpNav');const count=[amount,shares,nav].filter(Boolean).length;if(count<2)throw new Error('Introduce al menos dos datos entre importe, participaciones y VL.');if(!nav&&amount&&shares)nav=amount/shares;if(!shares&&amount&&nav)shares=amount/nav;if(!amount&&shares&&nav)amount=shares*nav;const c=tripletConsistency(amount,shares,nav);return{amount,shares,nav,inputDifferencePct:c.differencePct??0,inputConsistent:c.consistent}}
async function validateNavAgainstHistory(isin,requestDate,operationNav,windowDays=14,listingSymbol=null){try{await resolveFund(isin,true,false,listingSymbol)}catch{}const end=addDaysISO(requestDate,windowDays);let rows;if(listingSymbol){const raw=await select('listing_prices',`provider_symbol=eq.${encodeURIComponent(listingSymbol)}&price_date=gte.${requestDate}&price_date=lte.${end}&select=price_date,price,source,is_approximate&order=price_date.asc&limit=50`);rows=(raw||[]).filter(r=>r.is_approximate!==true).map(r=>({nav_date:r.price_date,nav:r.price,source:r.source}))}else{rows=await select('fund_navs',`isin=eq.${encodeURIComponent(isin)}&nav_date=gte.${requestDate}&nav_date=lte.${end}&select=nav_date,nav,source&order=nav_date.asc&limit=50`)}if(!Array.isArray(rows)||!rows.length)return{status:'no_reference',match:null,differencePct:null};let best=null;for(const row of rows){const ref=Number(row.nav);if(!Number.isFinite(ref)||ref<=0)continue;const diff=Math.abs(operationNav/ref-1)*100;const candidate={date:row.nav_date,nav:ref,source:row.source||'Supabase',differencePct:diff};if(diff<VALIDATION_TOLERANCE_PCT)return{status:'validated',match:candidate,differencePct:diff};if(!best||diff<best.differencePct)best=candidate}if(!best)return{status:'no_reference',match:null,differencePct:null};return{status:'nav_mismatch',match:best,differencePct:best.differencePct}}
async function validateTransferLeg(isin,requestDate,amount,shares){if(!amount||!shares)return{status:'missing_data',match:null,differencePct:null,nav:null};const nav=amount/shares;const r=await validateNavAgainstHistory(isin,requestDate,nav,21);return{...r,nav}}

function openNewOp(){document.getElementById('opContent').innerHTML=`<div class="drawer-head"><div><div class="eyebrow">Operaciones</div><div class="drawer-title">Nueva operación</div></div><button class="close" onclick="closeOp()">×</button></div><div class="segmented" id="typeSeg" style="margin:16px 0"><button class="active" data-type="Posición inicial">Inicial</button><button data-type="Base 2026">Base 2026</button><button data-type="Compra">Compra</button><button data-type="Aportación">Aportación</button><button data-type="Recurrente">Recurrente</button><button data-type="Reembolso">Reembolso</button><button data-type="Venta">Venta</button><button data-type="Traspaso">Traspaso</button></div><div id="dynamicForm"></div>`;document.getElementById('opBackdrop').classList.add('open');document.querySelectorAll('#typeSeg button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#typeSeg button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderOpForm(b.dataset.type)});renderOpForm('Posición inicial')}
